import unittest
from app import select

class Filters(unittest.TestCase):
    def test_filter(self):
        rows = [{'id': 1, 'status': 'paid'}, {'id': 2, 'status': 'pending'}]
        self.assertEqual(select(rows, 'paid'), rows[:1])
    def test_none(self):
        rows = [{'id': 2, 'status': 'pending'}]
        self.assertEqual(select(rows, None), rows)

if __name__ == '__main__':
    unittest.main()
